   resources[typeof(TabControl)]=(Style)XamlReader.Parse(@"<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='TabControl'><Setter Property='HorizontalContentAlignment' Value='Stretch'/><Setter Property='VerticalContentAlignment' Value='Stretch'/><Setter Property='Foreground' Value='{StaticResource CompassText}'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='TabControl'><DockPanel KeyboardNavigation.TabNavigation='Local'><WrapPanel x:Name='Headers' DockPanel.Dock='Top' IsItemsHost='True'/><ContentPresenter x:Name='PART_SelectedContentHost' ContentSource='SelectedContent' HorizontalAlignment='Stretch' VerticalAlignment='Stretch' Margin='0,3,0,0'/></DockPanel><ControlTemplate.Triggers><Trigger Property='TabStripPlacement' Value='Left'><Setter TargetName='Headers' Property='DockPanel.Dock' Value='Left'/><Setter TargetName='Headers' Property='Orientation' Value='Vertical'/></Trigger><Trigger Property='TabStripPlacement' Value='Right'><Setter TargetName='Headers' Property='DockPanel.Dock' Value='Right'/><Setter TargetName='Headers' Property='Orientation' Value='Vertical'/></Trigger><Trigger Property='TabStripPlacement' Value='Bottom'><Setter TargetName='Headers' Property='DockPanel.Dock' Value='Bottom'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>");
