    <Setter Property='Template'><Setter.Value><ControlTemplate TargetType='TabItem'><Border Margin='1' x:Name='TabFrame' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='1' CornerRadius='5' Padding='{TemplateBinding Padding}'><Grid><ContentPresenter x:Name='TabCaption' ContentSource='Header' RecognizesAccessKey='True' HorizontalAlignment='Center' VerticalAlignment='Center' Margin='0,1,0,2'/></Grid></Border><ControlTemplate.Triggers><Trigger Property='IsSelected' Value='True'><Setter TargetName='TabCaption' Property='TextElement.Foreground' Value='{StaticResource CompassAccent}'/><Setter TargetName='TabCaption' Property='TextElement.FontWeight' Value='SemiBold'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='TabFrame' Property='BorderThickness' Value='2'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
